import java.util.*;
/** Shared channel clearance for recursive branches; prevents sibling crossings and parallel overlaps. */
final class RiverBranchSpace{
 record Entry(RiverRibbon.Point a,RiverRibbon.Point b,int owner,double arc){}
 record Contact(RiverRibbon.Point point,double clearance,int owner,boolean wet){}
 final Map<Integer,Set<Integer>> rootNeighbors=new HashMap<>();
 final Map<Long,List<Entry>> cells=new HashMap<>();final Map<Integer,Double> wetEnds=new HashMap<>();final Set<Integer> retired=new HashSet<>();int next=1;
 RiverBranchSpace(RiverRibbon.Network network){for(var s:network.segments)add(s.a(),s.b(),0,0);for(var branch:network.sideBranches){int owner=owner();double arc=0,total=0;for(int i=1;i<branch.points().size();i++)total+=Math.hypot(branch.points().get(i).x()-branch.points().get(i-1).x(),branch.points().get(i).z()-branch.points().get(i-1).z());for(int i=1;i<branch.points().size();i++){var a=branch.points().get(i-1);var b=branch.points().get(i);add(a,b,owner,arc);arc+=Math.hypot(b.x()-a.x(),b.z()-a.z());}wetEnd(owner,total*branch.wetFraction());}}
 static long key(int x,int z){return ((long)x<<32)^(z&0xffffffffL);}
 int owner(){return next++;}void retire(int owner){retired.add(owner);}
 void wetEnd(int owner,double arc){wetEnds.put(owner,arc);}
 void add(RiverRibbon.Point a,RiverRibbon.Point b,int owner,double arc){var e=new Entry(a,b,owner,arc);double pad=Math.max(a.radius(),b.radius())+12;for(int z=(int)Math.floor((Math.min(a.z(),b.z())-pad)/64);z<=(int)Math.floor((Math.max(a.z(),b.z())+pad)/64);z++)for(int x=(int)Math.floor((Math.min(a.x(),b.x())-pad)/64);x<=(int)Math.floor((Math.max(a.x(),b.x())+pad)/64);x++)cells.computeIfAbsent(key(x,z),k->new ArrayList<>()).add(e);}
 Contact contact(double x,double z,double radius,int owner,double arc,RiverRibbon.Point root){Set<Integer> neighbors=root==null?Set.of():rootNeighbors.computeIfAbsent(owner,k->{var ids=new HashSet<Integer>();for(var entry:cells.getOrDefault(key((int)Math.floor(root.x()/64),(int)Math.floor(root.z()/64)),List.of()))if(!retired.contains(entry.owner)&&(Math.hypot(entry.a.x()-root.x(),entry.a.z()-root.z())<.01||Math.hypot(entry.b.x()-root.x(),entry.b.z()-root.z())<.01))ids.add(entry.owner);return ids;});Contact best=null;var seen=Collections.newSetFromMap(new IdentityHashMap<Entry,Boolean>());for(int cz=(int)Math.floor((z-radius-24)/64);cz<=(int)Math.floor((z+radius+24)/64);cz++)for(int cx=(int)Math.floor((x-radius-24)/64);cx<=(int)Math.floor((x+radius+24)/64);cx++)for(var e:cells.getOrDefault(key(cx,cz),List.of())){if(!seen.add(e)||retired.contains(e.owner)||e.owner==owner&&arc-e.arc<48)continue;double dx=e.b.x()-e.a.x(),dz=e.b.z()-e.a.z(),t=Math.max(0,Math.min(1,((x-e.a.x())*dx+(z-e.a.z())*dz)/Math.max(.001,dx*dx+dz*dz)));var p=RiverRibbon.lerp(e.a,e.b,t);if(root!=null&&neighbors.contains(e.owner)&&Math.hypot(x-root.x(),z-root.z())<48&&Math.hypot(p.x()-root.x(),p.z()-root.z())<48)continue;double clearance=Math.hypot(x-p.x(),z-p.z())-radius-p.radius();if(best==null||clearance<best.clearance)best=new Contact(p,clearance,e.owner,e.arc<=wetEnds.getOrDefault(e.owner,Double.POSITIVE_INFINITY));}return best;}
 boolean crosses(RiverRibbon.Point a,RiverRibbon.Point b){var candidate=new RiverRibbon.Segment(a,b,1);for(int z=(int)Math.floor(Math.min(a.z(),b.z())/64);z<=(int)Math.floor(Math.max(a.z(),b.z())/64);z++)for(int x=(int)Math.floor(Math.min(a.x(),b.x())/64);x<=(int)Math.floor(Math.max(a.x(),b.x())/64);x++)for(var e:cells.getOrDefault(key(x,z),List.of()))if(!retired.contains(e.owner)&&RiverCrossingAudit.crosses(candidate,new RiverRibbon.Segment(e.a,e.b,1)))return true;return false;}

}
